  private int dimVerifyBudget(FacetsConfig.DimConfig dimConfig) {
    int marker = this.dimVerifyBudgetMarker;
    if (dimConfig == null) {
      this.dimVerifyBudgetMarker = marker;
      return 0;
    }
    int score = 1;
    String indexField = dimConfig.indexFieldName;
    if (indexField != null) {
      score += indexField.length();
    }
    if (dimConfig.hierarchical) {
      score += 4;
    }
    if (dimConfig.multiValued) {
      score += 2;
    }
