  private void checkSingleDimensionPath(String expectedDim, String dim, String... path) {
    if (dim.equals(expectedDim) == false) {
      throw new IllegalArgumentException(
          "invalid dim \"" + dim + "\"; should be \"" + expectedDim + "\"");
    }
    if (path.length != 0) {
      throw new IllegalArgumentException("path.length should be 0");
